import {QueryRouteQueryType} from '@github-ui/react-core/future/data-router-types'
import {verifiedFetchJSON} from '@github-ui/verified-fetch'
import type {
  CopilotChatOrg,
  CopilotChatPayload,
  CopilotChatReference,
} from '@github-ui/copilot-chat/utils/copilot-chat-types'

export interface ChatPayload extends CopilotChatPayload {
  findFileWorkerPath: string
  refs?: CopilotChatReference[]
  ssoOrganizations?: CopilotChatOrg[]
}

async function fetchCopilotChatPayload(): Promise<ChatPayload> {
  const resp = await verifiedFetchJSON('/github-copilot/chat')
  if (!resp.ok) {
    throw new Error(`Failed to fetch chat provider: ${resp.statusText}`)
  }
  return (await resp.json()) as ChatPayload
}

export const copilotChatPayloadRouteQuery = {
  queryName: 'copilotChatPayload',
  queryFn: async (): Promise<ChatPayload> => fetchCopilotChatPayload(),
  type: QueryRouteQueryType.Blocking,
} as const
