import {useRouteQuery} from '@github-ui/react-core/future/use-route-query'
import {useCurrentQueryRoute} from '@github-ui/react-core/future/use-current-query-route'
import {CopilotIcon} from '@primer/octicons-react'
import {ErrorBoundary} from '@github-ui/react-core/error-boundary'
/* eslint-disable-next-line @github-ui/github-monorepo/no-use-app-payload --
   useAppPayload is deprecated. See
   https://thehub.github.com/epd/engineering/dev-practicals/frontend/react/data-router/migration/app-payload-deprecation/ */
import {AppPayloadContext} from '@github-ui/react-core/use-app-payload'
import {SidebarPageLayout} from '@github-ui/layout-primitives/SidebarPageLayout'
import {ContentView} from '@github-ui/pacer/ContentView'
import {useState, useEffect, useCallback, useRef, useMemo} from 'react'
import {useSearchParams} from '@github-ui/use-navigate'
import styles from './CopilotAgentsPage.module.css'

import {ConsecutiveCAPI401sProvider} from '@github-ui/agent-sessions/contexts/ConsecutiveCAPI401sContext'
import {CurrentUserProvider} from '@github-ui/agent-sessions/contexts/CurrentUserContext'
import {IntentDetectionProvider} from '@github-ui/agent-sessions/contexts/IntentDetectionContext'
import {useInitializeAuthToken} from '@github-ui/agent-sessions/hooks/use-initialize-auth-token'
import {useSSOChangeDetection} from '@github-ui/agent-sessions/hooks/use-sso-change-detection'
import {useCreateAPITask} from '@github-ui/agent-sessions/hooks/use-create-api-task'
import {useIcebreakers} from '@github-ui/agent-sessions/hooks/use-icebreakers'
import {AgentsBlankslate} from '@github-ui/agent-sessions/components/agents-view/AgentsBlankslate'
import {AgentsTaskList} from '@github-ui/agent-sessions/components/agents-view/AgentsTaskList'
import {AgentIcebreakers} from '@github-ui/agent-sessions/components/agents-view/AgentIcebreakers'
import {NewTaskChatInput} from '@github-ui/agent-sessions/components/new-task-chat-input/NewTaskChatInput'
import {AgentsSidebar, getActiveView} from '@github-ui/agent-sessions/components/agents-view/AgentsSidebar'
import {useRepoTasksFilter} from '@github-ui/agent-sessions/hooks/use-repo-tasks-filter'
import type {AgentTasksAppPayload} from '@github-ui/agent-sessions/types/agent-tasks-app-payload'
import {setTitle} from '@github-ui/document-metadata'
import {copilotAgentsRoute} from './copilot-agents-route'
import {CopilotChatProviders} from './CopilotChatProviders'
import type {ChatPayload} from './copilot-chat-payload-route-query'

export function CopilotAgentsPage() {
  const currentRoute = useCurrentQueryRoute()
  const {data: payload} = useRouteQuery(currentRoute, 'mainQuery')
  const {data: chatPayload} = useRouteQuery(copilotAgentsRoute, 'copilotChatPayload')

  if (!payload || !chatPayload) {
    return null
  }

  const typedPayload = payload as AgentTasksAppPayload

  return (
    <AppPayloadContext value={typedPayload}>
      <CurrentUserProvider currentUser={typedPayload.currentUser} currentUserIsSessionOwner>
        <ConsecutiveCAPI401sProvider>
          <ErrorBoundary boundaryName="CopilotAgentsPageContent">
            <CopilotAgentsPageContent payload={typedPayload} chatPayload={chatPayload} />
          </ErrorBoundary>
        </ConsecutiveCAPI401sProvider>
      </CurrentUserProvider>
    </AppPayloadContext>
  )
}

function CopilotAgentsPageContent({payload, chatPayload}: {payload: AgentTasksAppPayload; chatPayload: ChatPayload}) {
  useInitializeAuthToken(payload.initialAuthToken)
  useSSOChangeDetection(payload.initialAuthToken?.ssoOrgIDs)

  const [searchParams] = useSearchParams()
  const view = getActiveView(searchParams, payload.currentUser?.login)

  const [activeTab, setActiveTab] = useState<'active' | 'completed'>('active')
  const {repoFilter, setRepoFilter} = useRepoTasksFilter()

  useEffect(() => {
    setTitle('Agents · GitHub Copilot')
  }, [])

  if (!payload.agentsEnabled) {
    return (
      <SidebarPageLayout storageKey="copilot-agents-sidebar">
        <SidebarPageLayout.Content>
          <AgentsBlankslate
            hasCEorCBAccess={payload.hasCEorCBAccess}
            memberRequestEntities={payload.memberRequestEntities}
          />
        </SidebarPageLayout.Content>
      </SidebarPageLayout>
    )
  }

  let content: React.ReactNode
  if (view === 'home') {
    content = <HomeView payload={payload} chatPayload={chatPayload} />
  } else {
    const statuses = view === 'needs_attention' ? ['needs_attention'] : undefined
    content = (
      <AgentsTaskList
        activeTab={activeTab}
        setActiveTab={setActiveTab}
        repoFilter={repoFilter}
        setRepoFilter={setRepoFilter}
        statuses={statuses}
      />
    )
  }

  return (
    <SidebarPageLayout storageKey="copilot-agents-sidebar">
      <SidebarPageLayout.Sidebar aria-label="Agent navigation">
        <AgentsSidebar currentUserLogin={payload.currentUser?.login} />
      </SidebarPageLayout.Sidebar>
      <SidebarPageLayout.Content>
        <div className={styles.pageContainer}>
          <div className={styles.pageContent}>{content}</div>
        </div>
      </SidebarPageLayout.Content>
    </SidebarPageLayout>
  )
}

function HomeView({payload, chatPayload}: {payload: AgentTasksAppPayload; chatPayload: ChatPayload}) {
  const textAreaRef = useRef<HTMLTextAreaElement>(null)

  const taskListMutationConfig = useMemo(
    () => ({
      queryKey: ['agent-tasks', 1, 'active'] as readonly unknown[],
      getFlatTaskList: () => [],
      setFlatTaskList: () => {},
      pageSize: 10,
    }),
    [],
  )

  const {createTask} = useCreateAPITask({
    ...taskListMutationConfig,
  })

  const {
    visible: icebreakersVisible,
    handleSelect: handleIcebreakerSelect,
    handleDismiss: handleIcebreakerDismiss,
    handleIcebreakerSubmit,
  } = useIcebreakers({location: 'agents_page', variant: payload.icebreakerVariant})

  const handleUserSubmit = useCallback(
    async (
      content: string,
      selectedRepo: {nameWithOwner: string} | null,
      selectedBranch: string,
      selectedAgent: {subAgentSlug?: string; topLevelAgentId?: string} | undefined,
      _selectedMode?: string,
      modelId?: string,
    ) => {
      try {
        handleIcebreakerSubmit(content)
        const trimmedContent = content.trim()
        if (trimmedContent === '' || !selectedBranch || !selectedRepo) return

        createTask({
          nwo: selectedRepo.nameWithOwner,
          problemStatement: trimmedContent,
          baseRef: selectedBranch,
          eventType: 'agents_page',
          eventContent: trimmedContent,
          model: modelId,
          customAgent: selectedAgent?.subAgentSlug,
          agentId: selectedAgent?.topLevelAgentId,
          intentDetectionMode: 'task',
        })
      } catch {
        // Errors are handled by the createTask hook's error state
      }
    },
    [handleIcebreakerSubmit, createTask],
  )

  return (
    <CopilotChatProviders chatPayload={chatPayload}>
      <IntentDetectionProvider>
        <ContentView.Container width="small">
          <ContentView.Header>
            <div className={styles.pageIcon}>
              <CopilotIcon size={48} />
            </div>
          </ContentView.Header>
          <ContentView.Section>
            <NewTaskChatInput
              handleUserSubmit={handleUserSubmit}
              eventType="agents_page"
              textAreaRef={textAreaRef}
              agentQuotaSnapshot={payload.agentQuotaSnapshot}
            />
          </ContentView.Section>
          {icebreakersVisible && (
            <ContentView.Section>
              <AgentIcebreakers
                onSelect={handleIcebreakerSelect}
                onDismiss={handleIcebreakerDismiss}
                location="agents_page"
                variant={payload.icebreakerVariant}
              />
            </ContentView.Section>
          )}
        </ContentView.Container>
      </IntentDetectionProvider>
    </CopilotChatProviders>
  )
}
